The~\textit{graph Fourier basis} $\mathrm{V} \in \ensuremath{\mathbb{R}}^{N \times N}$ is defined to be the eigenvector matrix of $\mathrm{R}$, that is,
\begin{equation*}
	\mathrm{R} =  \mathrm{V} \Lambda \mathrm{V}^{-1},
\end{equation*}
where the $i$th column vector of $\mathrm{V}$ is the~\textit{graph Fourier basis vector} $\mathbf{v}_i$ corresponding to the eigenvalue $\lambda_i$ as the $i$th diagonal element in $\Lambda$.

When the graph representation matrix is the graph shift, the variation of a graph signal $\mathbf{x}$ is defined as,
\begin{equation*} 	\mathrm{S}_{\mathrm{A}} ( \mathbf{x} ) = \left\| \mathbf{x} - \frac{1}{\left\lvert\lambda_{\max}(\mathrm{A})\right\rvert} \mathrm{A} \mathbf{x} \right\|_2^2, \end{equation*}
 where $\lambda_{\max}(\mathrm{A})$ is the eigenvalue of $\mathrm{A}$ with the largest magnitude.

Let $\mathrm{D}$ be a graph dictionary, we define a class of graph signals by restricting
\begin{equation*}
 \mathbf{x} \ = \ \mathrm{D} \mathbf{a},
\end{equation*}
where $\mathbf{a}$ is a vector of expansion coefficients.

For the passive approach, the graph dictionary is designed only based on the graph structure; that is,
\begin{equation*}
 \mathrm{D}  = g(\mathrm{R}),
\end{equation*}
where $g(\cdot)$ is some operator on the graph structure matrix $\mathrm{R}$.

For the active approach, the graph dictionary is designed based on both graph structure and a set of given graph signals; that is,
\begin{equation*}
 \mathrm{D}  = g(\mathrm{A}, \mathrm{X}),
\end{equation*}
where $\mathrm{X}$ is a matrix representation of a set of graph signals.

Frame bounds. For any $\mathbf{x}$ in  a certain graph signal model,
\begin{equation*}
\alpha_1  \left\|  \mathbf{x}  \right\|_2 \leq  \left\| \mathrm{D} \mathbf{x}  \right\|_2 \leq  \alpha_2 \left\| \mathbf{x}  \right\|_2,
\end{equation*}
where $\alpha_1, \alpha_2$ are some constants;

Sparse representations. For any $\mathbf{x}$ in a certain graph signal model, there exists a sparse coefficient $\mathbf{a}$ with $\left\| \mathbf{a} \right\|_0 \leq C$, which satisfies 
\begin{equation*}
\left\| \mathbf{x} - \mathrm{D} \mathbf{a} \right\|_2^2  \leq \epsilon,
\end{equation*}
where $C, \epsilon$ are some constants;

Uncertainty principles. For  any $\mathbf{x}$ in a certain graph signal model,  the following is satisfied 
\begin{equation*}
\left\| \mathbf{a}_1 \right\|_0 + \left\| \mathbf{a}_2 \right\|_0   \geq C,
\end{equation*}
where $\left\| \mathbf{x} - \mathrm{D}_1 \mathbf{a}_1 \right\|_2^2  \leq \epsilon$ and
$\left\| \mathbf{x} - \mathrm{D}_2 \mathbf{a}_2 \right\|_2^2 \leq \epsilon$, and $\mathrm{D} = \begin{bmatrix}
\mathrm{D}_1 & \mathrm{D}_2
\end{bmatrix}$.

Let $\mathrm{F} \in \ensuremath{\mathbb{R}}^{N \times N}$ be a sampling pattern matrix, which is constrained by a given application and the sampling operator is 
\begin{equation} \Psi = \mathrm{C} \mathrm{F} \in \ensuremath{\mathbb{R}}^{M \times N},
\end{equation}
where $\mathrm{C} \in \ensuremath{\mathbb{R}}^{M \times N}$ selects rows from $\mathrm{F}$. For example, when we choose the $k$th row of $\mathrm{F}$ as the $i$th sample, the $i$th row of $\mathrm{C}$ is
\begin{equation*} \mathrm{C}_{i,j} = 
  \left\{ 
    \begin{array}{rl}
      1, & j = k;\\
      0, & \mbox{otherwise}.
  \end{array} \right.
\end{equation*}

\mathrm{C}_{i,j} = 
  \left\{ 
    \begin{array}{rl}
      1, & j = k;\\
      0, & \mbox{otherwise}.
  \end{array} \right.

A graph signal $\mathbf{x}$ with unit norm is~\emph{pairwise Lipschitz smooth} with parameter $C$ when it satisfies
\begin{equation*}
	| x_i - x_j |   \ \leq \  C \ d(v_i, v_j),~{\rm for~all~} i,j = 0, 1, \ldots, N-1,
\end{equation*}
with $d(v_i, v_j)$ the distance between the $i$th and the $j$th nodes.

A graph signal $\mathbf{x}$ with unit norm is~\emph{total Lipschitz smooth} with parameter $C$ when it satisfies
\begin{equation*}
	\sum_{(i,j) \in \mathcal{E}} \mathrm{W}_{i,j} ( x_i - x_j )^2   \ \leq \  C.
\end{equation*}

A graph signal $\mathbf{x}$ with unit norm  is~\emph{local normalized neighboring smooth  } with parameter $C$ when it satisfies
\begin{equation*}
	  \sum_i \left(  x_i -  \frac{1}{\sum_{j: (i,j) \in \mathcal{E}} \mathrm{W}_{i,j} }  \sum_{j: (i,j) \in \mathcal{E}} \mathrm{W}_{i,j} x_j  \right)^2  \ \leq \  C.
\end{equation*}

A graph signal $\mathbf{x}$ with unit norm  is~\emph{global normalized neighboring smooth} with parameter $C$ when it satisfies
\begin{equation*}
	  \sum_i \left(  x_i -  \frac{1}{ |\lambda_{\max}(\mathrm{W})| }  \sum_{j: (i,j) \in \mathcal{E}} \mathrm{W}_{i,j} x_j  \right)^2  \ \leq \  C.
\end{equation*}

A graph signal $\mathbf{x}$ is polynomial with degree $K$ when
\begin{equation*}
	\mathbf{x} \ = \  \mathrm{D}_{\rm poly(K)}  \mathbf{a} \ = \ \begin{bmatrix}
	{\bf 1}  &  \mathrm{D}^{(1)}  & \mathrm{D}^{(2)}  &  \ldots &  \mathrm{D}^{(K)} 
	\end{bmatrix} 
	\mathbf{a} \in \ensuremath{\mathbb{R}}^N,
\end{equation*}
where $\mathbf{a} \in \ensuremath{\mathbb{R}}^{KN+1}$ and $\mathrm{D}_{\rm poly(K)} $ is a graph polynomial dictionary with $\mathrm{D}^{(k)}_{i,j} = d^k(v_i, v_j)$. Denote this class by $\mathrm{PL}(K)$.

A graph signal $\mathbf{x}$ is bandlimited with respect to a graph Fourier basis $\mathrm{V}$ with bandwidth $K$ when
\begin{equation*}
	\mathbf{x} = \mathrm{V}_{(K)} \mathbf{a},
\end{equation*}
where $\mathbf{a} \in \ensuremath{\mathbb{R}}^{K}$ and $\mathrm{V}_{(K)}$ is a submatrix containing the first $K$ columns of $\mathrm{V}$. Denote this class by $\mathrm{BL}_{\mathrm{V}}(K)$~\cite{ChenVSK:15}.

A graph signal $\mathbf{x}$ is~\emph{$\epsilon$-vertex concentrated} on a graph vertex set $\Gamma$ when it satisfies
\begin{equation*}
	\left\| \mathbf{x} - \mathrm{I}_{\Gamma} \mathbf{x} \right\|_2^2 \leq \epsilon,
\end{equation*}
where $\mathrm{I}_{\Gamma} \in \ensuremath{\mathbb{R}}^{N \times N}$ is a diagonal matrix, with $(\mathrm{I}_{\Gamma})_{i,i} = 1$ when $i \in \Gamma$ and $0$, otherwise.

A graph signal $\mathbf{x}$ is~\emph{$\epsilon$-spectrum concentrated} on a graph spectrum band $\Omega$ when it satisfies
\begin{equation*}
	\left\| \mathbf{x} - \mathrm{V}_{\Omega} \mathrm{U}_{\Omega} \mathbf{x} \right\|_2^2 \leq \epsilon,
\end{equation*}
where $ \mathrm{V}_{\Omega} \in \ensuremath{\mathbb{R}}^{N \times |\Omega|}$ is a submatrix of $\mathrm{V}$ with columns selected by $\Omega$ and $ \mathrm{U}_{\Omega} \in \ensuremath{\mathbb{R}}^{|\Omega| \times N}$ is a submatrix of $\mathrm{V}$ with rows selected by $\Omega$.

({\bf Uncertainty principle of the graph vertex and spectrum domains}) Let a unit norm signal $\mathbf{x}$ supported on an undirected graph  be $\epsilon_{\Gamma}$-vertex concentrated and $\epsilon_{\Omega}$-spectrum concentrated at the same time. Then,
\begin{equation*}
|\Gamma| \cdot |\Omega| \geq  \frac{(1 - (\epsilon_{\Omega}  +  \epsilon_{\Gamma} ))^2 }{ \left\| \mathrm{U}_{\Omega} \right\|_{\infty}^2 }.
\end{equation*}

We first show $\left\| \mathrm{V}_{\Omega} \mathrm{U}_{\Omega}  \mathrm{I}_{\Gamma} \right\|_2 \leq \left\| \mathrm{U}_{\Omega} \right\|_{\infty}  \sqrt{ |\Gamma|\cdot |\Omega|}$.
\begin{eqnarray*}
&&	( \mathrm{V}_{\Omega} \mathrm{U}_{\Omega} \mathrm{I}_{\Gamma}  \mathbf{x} )_s
\ = \ \sum_{k \in \Omega} \mathrm{V}_{s,k} \left( \sum_{i \in \Gamma} \mathrm{U}_{k,i} x_i \right)
\\
& = &  \sum_{i \in \Gamma}  \left(   \sum_{k \in \Omega} \mathrm{V}_{s,k} \mathrm{U}_{k,i} \right) x_i
\ = \ \sum_i q(s,i) x_i,
\end{eqnarray*}
   where
   \begin{equation*} q(s,i) = 
  \left\{ 
    \begin{array}{rl}
      \sum_{k \in \Omega} \mathrm{V}_{s,k} \mathrm{U}_{k,i}, & i \in \Gamma;\\
      0, & \mbox{otherwise}.
  \end{array} \right.
\end{equation*}
Let $\mathbf{y}^{(i)}$ be a graph signal with $y^{(i)}_s = q(s,i)$. Then, $( \widehat{\mathbf{y}^{(i)}} )_k = {\bf 1}_{k \in \Omega} \mathrm{U}_{k,i}$. We then have
\begin{eqnarray*}
&&	\left\| \mathrm{V}_{\Omega} \mathrm{U}_{\Omega} \mathrm{I}_{\Gamma}  \right\|_{2}^2
 \ \leq \  \left\| \mathrm{V}_{\Omega} \mathrm{U}_{\Omega} \mathrm{I}_{\Gamma}  \right\|_{\rm HS}^2
\\
& = & \sum_{i \in \Gamma} \sum_{s} |q(s,i)|^2 
\ =  \sum_{i \in \Gamma} \left\| \mathbf{y}^{(i)} \right\|_2^2
\\
& = & \sum_{i \in \Gamma} \left\| \widehat{ \mathbf{y}^{(i)} } \right\|_2^2
\ = \  \sum_{i \in \Gamma} \sum_{k} \left( {\bf 1}_{k \in \Omega} \mathrm{U}_{k,i} \right)^2
\\
& \leq & \left\| \mathrm{U}_{\Omega} \right\|_{\infty}^2 \sum_{i \in \Gamma} \sum_{k} {\bf 1}_{k \in \Omega} 
\ = \   \left\| \mathrm{U}_{\Omega} \right\|_{\infty}^2 |\Gamma| \cdot |\Omega|.
\end{eqnarray*}

We then show that $\left\|  \mathrm{V}_{\Omega} \mathrm{U}_{\Omega} \mathrm{I}_{\Gamma} \mathbf{x}  \right\|_2 \geq 1 - (\epsilon_{\Omega}  +  \epsilon_{\Gamma} )$.
Based on the assumption, we have
   \begin{eqnarray*}
 &&  \left\| \mathbf{x} - \mathrm{V}_{\Omega} \mathrm{U}_{\Omega} \mathrm{I}_{\Gamma}  \mathbf{x}  \right\|_2
   \\
& = &   \left\| \mathbf{x} - \mathrm{I}_{\Gamma} \mathbf{x} \right\|_2  + \left\| \mathrm{I}_{\Gamma} \mathbf{x} -  \mathrm{V}_{\Omega} \mathrm{U}_{\Omega} \mathrm{I}_{\Gamma} \mathbf{x}  \right\|_2 
	\\
& \leq & \epsilon_{\Omega}  +  \epsilon_{\Gamma}. 
   \end{eqnarray*}
Since $\mathbf{x}$ has a unit norm, by the triangle inequality,  we have
   \begin{equation*}
  \left\|  \mathrm{V}_{\Omega} \mathrm{U}_{\Omega} \mathrm{I}_{\Gamma}  \right\|_2 \geq 1 - (\epsilon_{\Omega}  +  \epsilon_{\Gamma} ).
   \end{equation*}
Finally, we combine two results and obtain  
\begin{equation*}
|\Gamma|\cdot |\Omega|  \geq  \frac{\left\| \mathrm{V}_{\Omega} \mathrm{U}_{\Omega}  \mathrm{I}_{\Gamma} \right\|_2^2}{\left\| \mathrm{U}_{\Omega} \right\|_{\infty}^2 } \ > \ \frac{  (1 - (\epsilon_{\Omega}  +  \epsilon_{\Gamma} ))^2 }{ \left\| \mathrm{U}_{\Omega} \right\|_{\infty}^2}
\end{equation*}

q(s,i) = 
  \left\{ 
    \begin{array}{rl}
      \sum_{k \in \Omega} \mathrm{V}_{s,k} \mathrm{U}_{k,i}, & i \in \Gamma;\\
      0, & \mbox{otherwise}.
  \end{array} \right.

Prior work uses~\emph{inverse participation ratio} (IPR) to quantify localization~\cite{CucuringuM:11}. The IPR of a graph signal $\mathbf{x} \in \ensuremath{\mathbb{R}}^N$ is
\begin{equation*}
	{\rm IPR} = \frac{\sum_{i=1}^N x_i^{4}}{(\sum_{i=1}^N x_i^{2})^2}.
\end{equation*}

We next use \textit{normalized geodesic distance} (NGD) to quantify the clustered property.
Let $\mathcal{M}$ be the set of nodes that possesses 95\% energy of the whole signal. The normalized geodesic distance is defined as:
\begin{equation*}
	{\rm{NGD}} = \frac{1}{D}\frac{\sum_{ i, j \in \mathcal{M}, i \neq j}d(v_i,v_j)}{n(n-1)/2},
\end{equation*}
where $D$ is the diameter of the graph, $d(v_i,v_j)$ is the geodesic distance between nodes $i$ and $j$.

The recovery error is then
\begin{eqnarray*}
&&   \mathbf{x}^*_{\rm PLS}  - \mathbf{x}
\\
& = & \mathrm{D}_{\Omega}  (\Psi \mathrm{D}_{\Omega} )^{\dagger} \Psi ( \mathrm{D}_{\Omega^c} \mathbf{a}_{\Omega^c}  + \epsilon ),
\end{eqnarray*}
where the first term is bias and the second term is the variance from noise.

When we specify the matrix to be a graph structure matrix, we solve
\begin{eqnarray*}
 && \min_{\Psi \in \ensuremath{\mathbb{R}}^{M \times N} } \left\| \mathrm{R} - \mathrm{R} (\Psi \mathrm{R})^{\dagger} (\Psi \mathrm{R}) \right\|_{\xi},
\end{eqnarray*}
where $\Psi$ is the subsampling operator in~\eqref{eq:Psi}
 and $\xi = 2, F$.

\cite{BoutsidisDM:14} shows that 
\begin{eqnarray*}
\left\| \mathrm{R} - \mathrm{R} (\Psi \mathrm{R})^{\dagger} (\Psi \mathrm{R})  \right\|_{\xi}^2  \leq   
\left\| \mathrm{R}  - \mathrm{R}_K \right\|_{\xi}^2  \left\| \left( \Psi \mathrm{V}_{(K)} \right)^{\dagger} \Psi \right\|_2^2,
\end{eqnarray*}
where $\mathrm{R}_K$ is the best rank $K$ approximation of $\mathrm{R}$ and $\mathrm{V}_{(K)}$ is the first $K$ columns of the graph Fourier transform matrix of $\mathrm{R}$.

When the graph is unweighted and all the edge weights are nonnegative, the elements of the $i$th row of $\Delta$ are simply
\begin{equation*} \Delta_{i, \ell} = 
  \left\{ 
    \begin{array}{rl}
      1, & \ell = k;  \\
      -1, & \ell = j; \\
      0, & \mbox{otherwise}.
  \end{array} \right.
\end{equation*}

A graph signal $\mathbf{x} \in \ensuremath{\mathbb{R}}^N$ is~\emph{piecewise-constant} with $K \in
  \{0, 1, \cdots, N-1\}$ cuts, when it satisfies
  \begin{displaymath}
  \left\| \Delta \mathbf{x}  \right\|_0 \leq K.
\end{displaymath}

We can represent a local set $S$ by using a local-set-based graph signal, ${\bf 1}_{S} \in \ensuremath{\mathbb{R}}^N$, where
\begin{equation*}
\left(  {\bf 1}_{S}  \right)_i = 
  \left\{ 
    \begin{array}{rl}
      1, & v_i \in S;\\
      0, & \mbox{otherwise}.
  \end{array} \right.
\end{equation*}

A graph signal $\mathbf{x}$ is piecewise-constant based on local sets $\{S_c\}_{c=1}^C$ when
\begin{equation*}
	\mathbf{x} \ = \  \sum_{c=1}^C a_c {\bf 1}_{S_c},
\end{equation*}
where $\{S_c\}_{c=1}^C$ forms a valid series of local sets. Denote this class by $\mathrm{PC}(C)$.

A general multiresolution analysis on graphs consists of a sequence of embedded closed subspaces
\begin{equation*}
V_0 \subset  V_{1}  \subset V_{2}  \cdots \subset V_{K}
\end{equation*}
such that
\begin{itemize}
\item upward completeness
  \begin{equation*}
  		\bigcup_{i=0}^K  V_{i} = \ensuremath{\mathbb{R}}^N;
  \end{equation*}
\item downward completeness
  \begin{equation*}
  		\bigcap_{i=0}^K  V_{i} = \{ c {\bf 1_{\mathcal{V}}}, c \in \ensuremath{\mathbb{R}} \};
  \end{equation*}
\item existence of basis \  There exists an orthonormal basis $\{\Phi\}_{i}$ for $V_K$.
\end{itemize}

Let the local sets $S_{i+1,2j-1}, S_{i+1,2j}$ have the same parent local set $S_{i,j}$, the basis vector combing these two local sets is
\begin{eqnarray*}
&& \sqrt{ \frac{|S_{i+1,2j-1}| |S_{i+1,2j}|}{|S_{i+1,2j-1}|+|S_{i+1,2j}|}} \bigg(  \frac{1}{|S_{i+1,2j-1}|} {\bf 1}_{S_{i+1,2j-1}} 
\\
&& - \frac{1}{|S_{i+1,2j}|} {\bf 1}_{S_{i+1,2j}} \bigg).
\end{eqnarray*}

Another explanation is that when we recursively partition a node set into two local sets, each partition generates a wavelet basis vector. We still use Figure~\ref{fig:decomposition} as an example. In Partition 1, we partition the entire node set $S_{0,1} = \{1, 2, 3, 4 \}$ into $S_{1,1} =  \{1, 2 \}, S_{1,2} =  \{3, 4 \}$ and generate a basis vector   
\begin{eqnarray*}
&& \sqrt{ \frac{|S_{1,1}| |S_{1,2}|}{|S_{1,1}|+|S_{1,2}|}} \left(  \frac{1}{|S_{1,1}|} {\bf 1}_{S_{1,1}} - \frac{1}{|S_{1,2}|} {\bf 1}_{S_{1,2}}\right) 
\\
& = & \frac{1}{2}\begin{bmatrix}
1& 1 & -1 & -1
\end{bmatrix};
\end{eqnarray*}
in Partition 2, we partition $S_{1,1}$ into two disjoint connected sets $S_{2,1} =  \{1 \}, S_{2,2} =  \{ 2 \}$ and generate a basis vector   
\begin{eqnarray*}
&& \sqrt{ \frac{|S_{2,1} | |S_{2,2} |}{|S_{2,1} |+|S_{2,2} |}} \left(  \frac{1}{|S_{2,1} |} {\bf 1}_{S_{2,1} } - \frac{1}{|S_{2,2} |} {\bf 1}_{S_{2,2} }\right) 
\\
& = & \frac{1}{\sqrt{2}}\begin{bmatrix}
1& -1 & 0 & 0
\end{bmatrix};
\end{eqnarray*}
in Partition 3, we partition $S_{1,2}$ into $S_{2,3} =  \{3 \}, S_{2,4} =  \{ 4 \}$ and generate a basis vector   
\begin{eqnarray*}
&& \sqrt{ \frac{|S_{2,3}| |S_{2,4}|}{|S_{2,3}|+|S_{2,4}|}} \left(  \frac{1}{|S_{2,3}|} {\bf 1}_{S_{2,3}} - \frac{1}{|S_{2,4}|} {\bf 1}_{S_{2,4}}\right) 
\\
& = & \frac{1}{\sqrt{2}}\begin{bmatrix}
0 & 0 & 1 & -1
\end{bmatrix}.
\end{eqnarray*}

A series of local sets with a finer resolution is less smooth, that is, for all $i$,
\begin{equation*}
\sum_{j=1}^{2^i} \mathrm{S}_{\Delta, 0} (S_{i,j}) \leq  \sum_{j=1}^{2^{i+1}}  \mathrm{S}_{\Delta, 0}  (S_{i+1,j}) .
\end{equation*}

Let $\mathrm{W}$ be the output of Algorithm~\ref{alg:wavelet} and $T$ be the maximum level of the decomposition in Algorithm~\ref{alg:wavelet} . For all $\mathbf{x} \in \ensuremath{\mathbb{R}}^N$, we have
\begin{eqnarray*}
\left\| \mathrm{W}_{\rm LSPC}^T \mathbf{x} \right\|_0 \leq  \left\|  \Delta \mathbf{x} \right\|_0  T.
\end{eqnarray*}

When an edge $e \in {\rm Supp}(\Delta \mathbf{w})$, where Supp denotes the indices of nonzero elements, we call that the edge $\mathbf{e}$ is activated by the vector $\mathbf{w}$. Since each edge is activated at most once in each decomposition level, so each edge is activated by at most $T$ basis elements. Let activations($e$) be the number of basis elements in $\mathrm{W}_{\rm LSPC}$ that activates $e$. 
\begin{eqnarray*}
\left\| \mathrm{W}_{\rm LSPC}^T \mathbf{x} \right\|_0 \leq  \sum_{ e \in {\rm Supp}(\Delta \mathbf{w}) }  {\rm activations}(e) \leq \left\|  \Delta \mathbf{x} \right\|_0  T.
\end{eqnarray*}

For all $\mathbf{x} \in \ensuremath{\mathbb{R}}^N$,  we have $\left\| \mathbf{a}^* \right\|_0 \leq  2 T \left\|  \Delta \mathbf{x} \right\|_0$, where $T$ is the maximum level of the decomposition and
\begin{eqnarray*}
\mathbf{a}^* & = &   \arg \min_{\mathbf{a}}   \left\| \mathbf{a} \right\|_0, 
\\
   && {\rm subject~to:~}  \mathbf{x} \ = \ \mathrm{D}_{\rm LSPC} \mathbf{a}.
\end{eqnarray*}

Let the local-set-based wavelet basis evenly partition the node set each time. We have
\begin{eqnarray*}
\left\| \mathrm{W}_{\rm LSPC}^T \mathbf{x} \right\|_0 \leq  \left\|  \Delta \mathbf{x} \right\|_0 \ceil*{\log N}.
\end{eqnarray*}

Let $\mathrm{W}$ be the local-set-based wavelet basis with the even partition. Then,
\begin{eqnarray*}
 \mathrm{W}_{\rm LSPC} & = & \arg \min_{\mathrm{F}}  \max_{\mathbf{x} \in \{ \left\|  \Delta \mathbf{x} \right\|_0 \leq K \} }  \left\|  \mathrm{F}^T \mathbf{x} \right\|_0, 
 \\
 && {\rm subject~to}: \mathrm{F} {\rm~is~orthornormal}.
\end{eqnarray*}

Let $m$ be the number of samples.
 We use the multiresolution decomposition of the local sets as shown in Section~\ref{sec:Dict_LSPC}.
 Instead of obtaining a full decomposition tree, we partition the local sets until we obtain $m$ leaf local sets. Those local sets may not be in the same decomposition level , but the union of them still cover the entire space. For the local sets in the same level of the decomposition tree, we first partition the one that has the largest number of nodes. For each leaf local set, we choose a center that has the minimum summation of the geodesic distances to all the other nodes in the leaf local set. We use those centers for the $M$  leaf local sets as the sampled set. Let $\mathbf{x} \in \ensuremath{\mathbb{R}}^N$ be a piecewise-constant graph signal, $\mathcal{M} = (\mathcal{M}_1, \cdots, \mathcal{M}_M)$ be the designed sampled set, with each sampled node $\mathcal{M}_j$ be the center of the $j$th leaf local set $S_j$. The recovered graph signal is 
\begin{equation*}
\mathbf{x}' \ = \   \sum_{j=1}^{M}  x_{\mathcal{M}_j} {\bf 1}_{S_j}.
\end{equation*}

Let the original graph signal $\mathbf{x} \in \mathrm{PC}_G(K)$.
The recovery error is bounded as
\begin{eqnarray*}
\sum_{i=1}^{N} \mathrm{I} ( x_i \neq x'_i ) \leq K \max_{j = 1, \cdots, M} | S_j |,
\end{eqnarray*}
where $\mathrm{I} (\cdot)$ is the indicator function.

A graph signal $\mathbf{x}$ is piecewise-polynomial with $C$ pieces and degree $K$ when
\begin{equation*}
	\mathbf{x} \ = \  \sum_{c=1}^C  \mathbf{x}^{(c)}  {\bf 1}_{ S_c},
\end{equation*}
where $\mathbf{x}^{(c)}$ is a $k$th order polynomial signal on the subgraph $G_{S_c}$ with $x^{(c)}_i  \ = \   a_{c} + \sum_{j \in S_c} \sum_{k=1}^K a_{k, j, c} d^k(v_i, v_j). $
Denote this class by $\mathrm{PPL}(C, K)$.

A graph signal $\mathbf{x}$ is piecewise-bandlimited with $C$ pieces and bandwidth $K$ when
\begin{equation*}
	\mathbf{x} \ = \  \sum_{c=1}^C  \mathbf{x}^{(c)}  {\bf 1}_{ S_c},
\end{equation*}
where $\mathbf{x}^{(c)}$ is a bandlimited signal on the subgraph $G_{S_c}$ with $x^{(c)}_i = \sum_{k=0}^K a_{k, c} \mathrm{V}^{(c)}_{i,k}$, and $\mathrm{V}^{(c)}$ is a graph Fourier basis of $G_{S_c}$.
Denote this class by $\mathrm{PBL}_{\mathrm{V}}(C, K)$.

For each local set, 
\begin{equation*}
	\mathrm{D}_{S_{i, j}}   \ = \ \begin{bmatrix}
	{\bf 1}  &  \mathrm{D}^{(1)}_{S_{i, j}}  &  \mathrm{D}^{(2)}_{S_{i, j}}   &  \ldots &  \mathrm{D}^{(K)}_{S_{i, j}} 
	\end{bmatrix},
\end{equation*}
where  $(  \mathrm{D}_{S_{i, j}}^{(k)} )_{m,n}  = d^k(v_m, v_n)$, when $v_m, v_n \in S_{i,j}$; and 0, otherwise.

Under the null, we have $\left\| \mathbf{a}_{\mathbf{e}}^* \right\|_{\infty} < \sigma \sqrt{2 \log( KNT /\delta)}$ with probability at least $1-\delta$. We set $\tau = \sigma \sqrt{2 \log(KNT/\delta)}$ to control the type 1 error.

For the alternative, $\left\| \mathbf{a}_{\mathbf{y}}^* \right\|_{\infty} \geq \left\| \mathbf{a}_{\mathbf{x}}^* \right\|_{\infty} - \sigma \sqrt{2 \log(KNT/\delta)}$ with probability $1-\delta$. In Theorem~\ref{thm:PPL}, we see that it is feasible to have $\left\| \mathbf{x} - \mathrm{D}_{\rm LSPS} \mathbf{a}_{\mathbf{x}} \right\|_2^2 \leq \epsilon_{\rm par} \left\| \mathbf{x} \right\|_2^2$ with $\left\| \mathbf{a}_{\mathbf{x}} \right\|_0 = 2KT  \left\| \Delta \mathbf{x}_{\rm PC} \right\|_0$. We then have
\begin{eqnarray*}
 \left\| \mathbf{a}_{\mathbf{x}}^* \right\|_{\infty} \geq  \frac{ \left\| \mathbf{a}_{\mathbf{x}}^* \right\|_{2}  }{ \sqrt{ \left\| \mathbf{a}_{\mathbf{x}}^* \right\|_0 } } 
\geq 
  \frac{ 1 - \sqrt{ \epsilon_{\rm par}}}{ \left\| (\mathrm{D}_{\rm LSPS})_{\Omega} \right\|_2 \sqrt{ 2KT  \left\| \Delta \mathbf{x}_{\rm PC} \right\|_0  } }   \left\| \mathbf{x} \right\|_2,
\end{eqnarray*}
where $\Omega$ is the support of zero elements in $\mathbf{a}_{\mathbf{x}}^*$. Then, we force the lower bound of $\left\| \mathbf{a}_{\mathbf{y}}^* \right\|_{\infty} $ to control the type 2 error.

We then show that $\left\|  \mathrm{V}_{\Omega} \mathrm{U}_{\Omega} \mathrm{I}_{\Gamma} \mathbf{x}  \right\|_2 \geq 1 - (\epsilon_{\Omega}  +  \epsilon_{\Gamma} )$.
Based on the assumption, we have
   \begin{eqnarray*}
